package dev.manasmadan.backstage.mesh

/**
 * The Kotlin port, checked against fixtures generated by the Go reference.
 *
 * This runs as a plain JVM program rather than as an Android instrumentation test,
 * deliberately: everything it exercises is pure Kotlin with no Android imports, so it
 * can be compiled and run with `kotlinc` on any machine, in CI, without an SDK or an
 * emulator. `apps/backstage-android/verify.sh` does exactly that.
 *
 * The fixtures come from `internal/mesh/testdata/conformance.json`, which is generated
 * by the Go implementation. Regenerate both sides together:
 *
 *     GATECRASH_UPDATE_FIXTURES=1 go test ./internal/mesh -run ConformanceFixture
 *
 * If a value below stops matching, the two implementations have diverged, and the
 * consequence is not a failing test — it is a message that never arrives.
 */

private var failures = 0

private fun check(name: String, condition: Boolean, detail: String = "") {
    if (condition) {
        println("  ok    $name")
    } else {
        println("  FAIL  $name${if (detail.isEmpty()) "" else " — $detail"}")
        failures++
    }
}

private fun checkEquals(name: String, want: String, got: String) =
    check(name, want == got, "want $want, got $got")

private fun hex(bytes: ByteArray): String = bytes.joinToString("") { "%02x".format(it) }

private fun unhex(text: String): ByteArray =
    ByteArray(text.length / 2) { text.substring(it * 2, it * 2 + 2).toInt(16).toByte() }

private fun messageId(value: Long): ByteArray {
    val out = ByteArray(8)
    for (i in 0 until 8) out[i] = (value shr (8 * (7 - i))).toByte()
    return out
}

// ---------------------------------------------------------------------------
// The fixtures, from internal/mesh/testdata/conformance.json
// ---------------------------------------------------------------------------

private const val FRAME_ENCODED = "010101040102030405060708090a0b0c000068656c6c6f206d657368"
private const val FRAME_AAD = "010101000102030405060708090a0b0c0000"
private const val FRAME_HOPPED_AAD = "010101000102030405060708090a0b0c0000"

/** A hand-driven clock, so nothing here sleeps and every run is identical. */
private class Clock(var millis: Long = 1_600_000_000_000) {
    fun now(): Long = millis
    fun advance(by: Long) { millis += by }
}

private fun theFrameEncodesLikeGo() {
    println("\nthe frame encodes exactly as the Go reference does")

    val frame = Frame(
        kind = Kind.CHANNEL,
        flags = Flags.PRIORITY,
        ttl = 4,
        id = messageId(0x0102030405060708L),
        channel = byteArrayOf(9, 10, 11, 12),
        body = "hello mesh".toByteArray(),
    )

    checkEquals("encoded bytes", FRAME_ENCODED, hex(frame.encode()))
    checkEquals("additional authenticated data", FRAME_AAD, hex(frame.aad()))

    val hopped = frame.hop()
    check("a frame with ttl 4 hops", hopped != null)
    check("the ttl decremented", hopped?.ttl == 3, "got ${hopped?.ttl}")

    // The single most important property in the codec. Every relay decrements the TTL, so
    // a TTL under the tag would mean a frame failed to authenticate at the first hop and
    // the mesh would not work at all.
    checkEquals("the hopped frame's aad is unchanged", FRAME_HOPPED_AAD, hex(hopped!!.aad()))
    check("aad ignores the ttl", hex(frame.aad()) == hex(hopped.aad()))
}

private fun theFrameDecodesWhatGoEncoded() {
    println("\nthe frame decodes what Go encoded")

    val frame = Frame.decode(unhex(FRAME_ENCODED))
    check("kind", frame.kind == Kind.CHANNEL, "got ${frame.kind}")
    check("priority flag", frame.isPriority)
    check("ttl", frame.ttl == 4, "got ${frame.ttl}")
    checkEquals("message id", "0102030405060708", hex(frame.id))
    checkEquals("channel id", "090a0b0c", hex(frame.channel))
    check("body", frame.body.decodeToString() == "hello mesh", "got ${frame.body.decodeToString()}")
    check("not a fragment", !frame.isFragment)
}

private fun everyFieldIsAuthenticatedExceptTheTtl() {
    println("\nevery header field except the ttl is authenticated")

    val base = Frame(
        kind = Kind.CHANNEL, ttl = 6, id = messageId(1),
        channel = byteArrayOf(1, 2, 3, 4), body = "x".toByteArray(),
    )
    val aad = hex(base.aad())

    check("re-labelling the kind changes the aad", hex(base.copy(kind = Kind.DIRECT).aad()) != aad)
    check("promoting to priority changes the aad", hex(base.copy(flags = Flags.PRIORITY).aad()) != aad)
    check("changing the id changes the aad", hex(base.copy(id = messageId(2)).aad()) != aad)
    check(
        "changing the channel changes the aad",
        hex(base.copy(channel = byteArrayOf(9, 9, 9, 9)).aad()) != aad,
    )
    check(
        "changing the fragment position changes the aad",
        hex(base.copy(flags = Flags.FRAGMENT, fragmentIndex = 1, fragmentTotal = 2).aad()) != aad,
    )
    check("decrementing the ttl does not", hex(base.hop()!!.aad()) == aad)
}

private fun decodeRejectsWhatItShould() {
    println("\ndecode rejects what it should")

    fun rejects(name: String, mutate: (ByteArray) -> ByteArray) {
        val raw = mutate(unhex(FRAME_ENCODED))
        val rejected = try {
            Frame.decode(raw)
            false
        } catch (_: FrameError) {
            true
        }
        check(name, rejected)
    }

    rejects("a frame shorter than a header") { it.copyOfRange(0, 4) }
    rejects("an unknown version") { it.copyOf().also { c -> c[0] = 99 } }
    rejects("a ttl past the limit") { it.copyOf().also { c -> c[3] = (MAX_TTL + 1).toByte() } }
    rejects("an unknown kind") { it.copyOf().also { c -> c[1] = 42 } }
    rejects("a frame larger than the maximum") { ByteArray(MAX_FRAME + 1).also { c -> c[0] = VERSION } }
    rejects("a fragment claiming a total of one") {
        it.copyOf().also { c -> c[2] = (c[2].toInt() or Flags.FRAGMENT).toByte(); c[17] = 1 }
    }
    rejects("a fragment index at its total") {
        it.copyOf().also { c -> c[2] = (c[2].toInt() or Flags.FRAGMENT).toByte(); c[16] = 3; c[17] = 3 }
    }
    rejects("a fragment position without the flag") { it.copyOf().also { c -> c[17] = 3 } }
}

private fun fragmentationRoundTrips() {
    println("\nfragmentation round-trips, out of order")

    val body = ByteArray(600) { (it % 251).toByte() }
    val frames = Frame.fragment(Frame(kind = Kind.CHANNEL, id = messageId(1)), body)

    check("split into four", frames.size == 4, "got ${frames.size}")
    check("every piece is flagged", frames.all { it.isFragment })
    check("every piece fits a frame", frames.all { it.size <= MAX_FRAME })

    // Keyed on the message id alone, fragment two would look like a duplicate of
    // fragment one and the message would never arrive.
    check(
        "each fragment has its own dedup key",
        frames.map { hex(it.dedupKey) }.toSet().size == frames.size,
    )

    val clock = Clock()
    val reassembler = Reassembler(now = clock::now)
    var complete: Frame? = null
    // Out of order, because fragments take different paths across a crowd.
    for (index in listOf(2, 0, 3, 1)) {
        reassembler.accept(frames[index])?.let { complete = it }
    }

    check("reassembled", complete != null)
    check("the body survived", complete?.body?.contentEquals(body) == true)
    check("the fragment flag is cleared", complete?.isFragment == false)

    val short = Frame(kind = Kind.CHANNEL, id = messageId(2), body = "short".toByteArray())
    check(
        "an unfragmented frame completes immediately",
        Reassembler(now = clock::now).accept(short) != null,
    )
}

private fun reassemblyIsBounded() {
    println("\nreassembly is bounded, because it is memory a stranger can make us allocate")

    val clock = Clock()
    val reassembler = Reassembler(limit = 2, now = clock::now)
    for (i in 0 until 10) {
        val frames = Frame.fragment(Frame(kind = Kind.CHANNEL, id = messageId(i.toLong())), ByteArray(400))
        reassembler.accept(frames[0])
    }
    check("holds at most the limit", reassembler.pending <= 2, "holding ${reassembler.pending}")

    val frames = Frame.fragment(Frame(kind = Kind.CHANNEL, id = messageId(99)), ByteArray(400))
    val expiring = Reassembler(timeoutMillis = 30_000, now = clock::now)
    expiring.accept(frames[0])
    check("a partial message is held", expiring.pending == 1)
    clock.advance(60_000)
    check("and expires", expiring.pending == 0)

    var tooBig = false
    try {
        Frame.fragment(Frame(kind = Kind.CHANNEL, id = messageId(1)), ByteArray(MAX_FRAGMENTS * MAX_BODY + 1))
    } catch (_: IllegalArgumentException) {
        tooBig = true
    }
    check("an oversized message is refused", tooBig)
}

private fun theHashAgreesWithGo() {
    println("\nthe cuckoo hashing agrees with the Go reference")

    // Every value here came from `go test ./internal/cuckoo -run HashVectorsForThePorts -v`.
    // Unsigned 64-bit arithmetic is the easiest place in this protocol to get a plausible
    // wrong answer, and a wrong bucket index does not look like a bug — it looks like a
    // mesh with a worse delivery rate.
    checkEquals("splitmix64(0)", "e220a8397b1dcdaf", "%016x".format(splitmix(0uL).toLong()))
    checkEquals("splitmix64(1)", "910a2dec89025cc1", "%016x".format(splitmix(1uL).toLong()))
    checkEquals("splitmix64(2)", "975835de1c9756ce", "%016x".format(splitmix(2uL).toLong()))
    checkEquals(
        "splitmix64(2^64-1)",
        "e4d971771b652c20",
        "%016x".format(splitmix(ULong.MAX_VALUE).toLong()),
    )

    // FNV-1a finished with splitmix, which is what both the dedup filter and the box's
    // bloom filter are built on.
    checkEquals("fnv1a64(\"\")", "c3817c016ba4ff30", "%016x".format(fnv1a(ByteArray(0)).toLong()))
    checkEquals(
        "fnv1a64(\"gatecrash\")",
        "3c3fe25f978210f0",
        "%016x".format(fnv1a("gatecrash".toByteArray()).toLong()),
    )
    checkEquals(
        "fnv1a64(\"backstage\")",
        "d31a88fed4c80c5f",
        "%016x".format(fnv1a("backstage".toByteArray()).toLong()),
    )
}

private fun theFilterNeverForgetsWhatItWasTold() {
    println("\nthe dedup filter has no false negatives")

    val filter = CuckooFilter(4096)
    var inserted = 0
    for (i in 0 until 3000) {
        if (filter.insert(messageId(i.toLong()))) inserted++
    }
    check("stored three thousand ids", inserted == 3000, "stored $inserted")

    var missing = 0
    for (i in 0 until 3000) if (!filter.contains(messageId(i.toLong()))) missing++
    check("none were forgotten", missing == 0, "$missing forgotten")

    // A false positive costs one unrelayed message; the 16-bit fingerprint is what keeps
    // that rare. At 8 bits this would be around 3%.
    var positives = 0
    val probes = 100_000
    for (i in 1_000_000 until 1_000_000 + probes) {
        if (filter.contains(messageId(i.toLong()))) positives++
    }
    val rate = positives.toDouble() / probes
    check("the false positive rate is under 0.1%", rate < 0.001, "measured %.4f%%".format(rate * 100))
    println("        false positive rate %.4f%%".format(rate * 100))
}

private fun theFilterFillsUpProperly() {
    println("\nthe filter reaches a useful load factor")

    val filter = CuckooFilter(1 shl 16)
    var inserted = 0
    while (filter.insert(messageId(inserted.toLong()))) {
        inserted++
        if (inserted > filter.capacity) break
    }
    val load = inserted.toDouble() / filter.capacity
    // Below 90% means the alternate-bucket derivation is wrong — most likely the
    // fingerprint is being xored in without being mixed first, which confines both homes
    // to one neighbourhood.
    check("fills past 90%", load >= 0.90, "filled to %.1f%%".format(load * 100))
    println("        load factor %.1f%%".format(load * 100))
}

private fun seenIdsExpire() {
    println("\nseen ids expire, so the filter cannot fill up forever")

    val clock = Clock()
    val seen = SeenSet(capacity = 1024, windowMillis = 600_000, now = clock::now)

    check("a new id is not seen", !seen.seen(messageId(1)))
    check("and is remembered", seen.seen(messageId(1)))

    clock.advance(660_000)
    check("still remembered after one window", seen.seen(messageId(1)))

    clock.advance(660_000)
    seen.seen(messageId(2))
    clock.advance(660_000)
    check("forgotten after two windows", !seen.seen(messageId(1)))

    // The panic wipe.
    for (i in 0 until 100) seen.seen(messageId(i.toLong()))
    seen.wipe()
    check("a wipe leaves nothing", seen.size == 0, "${seen.size} survived")

    check("the whole set is a few tens of kilobytes", seen.bytes <= 64 * 1024, "${seen.bytes} bytes")
    println("        two generations of 1024 ids: ${seen.bytes} bytes")
}

private fun theRouterMakesTheRightDecisions() {
    println("\nthe router relays, deduplicates, and gives way to density")

    val clock = Clock()
    var draw = 0.0
    val router = Router(k = 3.0, now = clock::now, random = { draw })

    val frame = Frame(kind = Kind.CHANNEL, ttl = 4, id = messageId(1), body = "x".toByteArray())

    val first = router.handle(frame, "peer-a")
    check("a new frame is delivered", first.deliver)
    check("and relayed", first.relay)

    val second = router.handle(frame, "peer-b")
    check("a duplicate is not delivered", !second.deliver)
    check("and not relayed", !second.relay)

    // A phone must not show its owner its own message coming back from a neighbour.
    val mine = router.originate(Frame(kind = Kind.CHANNEL, id = messageId(7), body = "hi".toByteArray()))
    check("an originated frame gets the full ttl", mine.ttl == MAX_TTL, "got ${mine.ttl}")
    check("and comes back as a duplicate", !router.handle(mine.hop()!!, "peer-a").deliver)

    // At the hop limit: delivered locally, not relayed.
    val exhausted = router.handle(Frame(kind = Kind.CHANNEL, ttl = 0, id = messageId(9)), "peer")
    check("a frame at the hop limit is delivered", exhausted.deliver)
    check("but not relayed", !exhausted.relay)

    // A beacon is never relayed: the feature works by hearing it directly.
    val beacon = router.handle(
        Frame(kind = Kind.BEACON, ttl = 0, id = messageId(11), body = byteArrayOf(1, 2, 3, 4)),
        "peer",
    )
    check("a beacon is delivered", beacon.deliver)
    check("and never relayed", !beacon.relay)

    // Density: with three hundred neighbours the probability collapses, and an ordinary
    // frame stops relaying while an announcement does not.
    check("an isolated node relays unconditionally", Router(now = clock::now, random = { 0.9 }).relayProbability() == 1.0)
    for (i in 0 until 300) router.observe("peer-$i")
    val probability = router.relayProbability()
    check("the probability falls with density", probability in 0.001..0.05, "got %.4f".format(probability))
    println("        %d neighbours -> relay probability %.4f".format(router.neighborCount(), probability))

    draw = 0.99
    check(
        "an ordinary frame does not relay in a saturated crowd",
        !router.handle(Frame(kind = Kind.CHANNEL, ttl = 4, id = messageId(21)), "peer").relay,
    )
    check(
        "an announcement does",
        router.handle(
            Frame(kind = Kind.ANNOUNCEMENT, flags = Flags.PRIORITY, ttl = 4, id = messageId(22)),
            "peer",
        ).relay,
    )

    // The carry buffer is only offered where flooding does not reach.
    check("a dense node does not push its carry buffer", !router.shouldOfferCarry())
    val lonely = Router(k = 3.0, now = clock::now, random = { 0.0 })
    check("a sparse one does", lonely.shouldOfferCarry())

    // Jitter: without it every relayer transmits at the same instant and collides.
    var jittered = Router(now = clock::now, random = { 0.5 }, maxJitterMillis = 200)
    val decision = jittered.handle(Frame(kind = Kind.CHANNEL, ttl = 4, id = messageId(31)), "peer")
    check("a relay is jittered", decision.afterMillis == 100L, "got ${decision.afterMillis}ms")

    // Density forgets phones that walked away, or the estimate only ever rises.
    clock.advance(60_000)
    check("neighbours are forgotten", router.neighborCount() == 0, "${router.neighborCount()} remain")
}

private fun densityForgetsAndWipeClears() {
    println("\na wipe leaves no trace of what the phone heard")

    val clock = Clock()
    val router = Router(now = clock::now, random = { 0.0 })
    for (i in 0 until 20) {
        router.observe("peer-$i")
        router.handle(Frame(kind = Kind.CHANNEL, ttl = 4, id = messageId(i.toLong())), "peer")
    }

    router.wipe()
    check("no carried frames", router.carriedFrames().isEmpty())
    check("no neighbours", router.neighborCount() == 0)
    check(
        "a previously seen message is new again",
        router.handle(Frame(kind = Kind.CHANNEL, ttl = 4, id = messageId(0)), "peer").deliver,
    )
}

/**
 * The frames the UI actually sends.
 *
 * Here because the bug this catches is invisible to a compiler and fatal at runtime: the
 * first version built its message id as 12 bytes, and Frame's precondition rejects
 * anything but 8. It compiled, installed, and would have thrown the moment somebody
 * pressed Send. A wire constant is exactly the thing to assert rather than remember.
 */
private fun theUiBuildsSendableFrames() {
    println("\nthe frames the UI sends are on-format")

    val id = ByteArray(ID_SIZE) { (it + 1).toByte() }

    val chat = chatFrame("north gate is backing up", urgent = false, id = id)
    check("a chat message is a channel frame", chat.kind == Kind.CHANNEL)
    check("and is not priority", !chat.isPriority)
    check("and encodes", chat.encode().size == HEADER_SIZE + "north gate is backing up".length)

    val sos = chatFrame("SOS", urgent = true, id = id)
    check("an SOS is still a channel frame", sos.kind == Kind.CHANNEL)
    check("but carries the priority flag", sos.isPriority)

    // The priority flag is what makes an SOS cross a saturated field: an ordinary frame
    // relays with probability k/n, a priority one relays unconditionally.
    val crowd = Router(now = { 0L }, random = { 0.99 })
    repeat(300) { crowd.observe("peer-$it") }
    check(
        "an SOS relays in a crowd where chatter does not",
        crowd.handle(sos, "peer-0").relay && !crowd.handle(chat, "peer-1").relay,
    )

    // Truncated, not rejected, and still a legal frame.
    val long = chatFrame("x".repeat(MAX_BODY + 40), urgent = false, id = id)
    check("an over-long body is truncated to the maximum", long.body.size == MAX_BODY)
    check("and the frame still encodes", long.encode().size == MAX_FRAME)

    var threw = false
    try {
        chatFrame("hi", urgent = false, id = ByteArray(12))
    } catch (_: IllegalArgumentException) {
        threw = true
    }
    check("a wrong-sized id is refused rather than silently reshaped", threw)
}

fun main() {
    println("Backstage protocol conformance — Kotlin against the Go reference")

    theFrameEncodesLikeGo()
    theFrameDecodesWhatGoEncoded()
    everyFieldIsAuthenticatedExceptTheTtl()
    decodeRejectsWhatItShould()
    fragmentationRoundTrips()
    reassemblyIsBounded()
    theHashAgreesWithGo()
    theFilterNeverForgetsWhatItWasTold()
    theFilterFillsUpProperly()
    seenIdsExpire()
    theRouterMakesTheRightDecisions()
    densityForgetsAndWipeClears()
    theUiBuildsSendableFrames()

    println()
    if (failures > 0) {
        println("$failures checks failed — the Kotlin port and the Go reference disagree")
        kotlin.system.exitProcess(1)
    }
    println("every check passed; the Kotlin port agrees with the Go reference")
}
